import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = list(reader)

    header_index = None
    for i, record in enumerate(records):
        normalized = [value.lstrip("\ufeff").strip().lower() for value in record]
        if (
            "department" in normalized
            and "organisation name" in normalized
            and "hng ref no" in normalized
            and "project name" in normalized
        ):
            header_index = i
            break

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = [value.lstrip("\ufeff") for value in records[header_index]]
    width = len(columns)
    rows = []

    for record in records[header_index + 1:]:
        if not any(value.strip() for value in record):
            continue

        if len(record) > width and width >= 8:
            # Preserve surplus unquoted commas in the free-text description.
            record = record[:4] + [",".join(record[4:len(record) - 3])] + record[-3:]

        if len(record) < width:
            record.extend([""] * (width - len(record)))
        elif len(record) > width:
            record = record[:width - 1] + [",".join(record[width - 1:])]

        rows.append(record)

    return {"columns": columns, "rows": rows}
